from AlgorithmImports import *
from math import floor


class ExactStrategyAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.spy = self.AddEquity("SPY", Resolution.Daily).Symbol
        self.aapl = self.AddEquity("AAPL", Resolution.Daily).Symbol
        self.ibm = self.AddEquity("IBM", Resolution.Daily).Symbol
        self.bac = self.AddEquity("BAC", Resolution.Daily).Symbol
        self.aig = self.AddEquity("AIG", Resolution.Daily).Symbol

        self.symbols = [self.spy, self.aapl, self.ibm, self.bac, self.aig]

        self.spy_sma = self.SMA(self.spy, 100, Resolution.Daily)
        self.aapl_rsi = self.RSI(
            self.aapl,
            14,
            MovingAverageType.Wilders,
            Resolution.Daily
        )

        self.previous_spy_close = None
        self.previous_spy_sma = None
        self.previous_aapl_close = None
        self.aapl_red_streak = 0

        self.strategy_a_lot = 0
        self.strategy_b_lot = 0

        self.strategy_a_pending = None
        self.strategy_b_pending = None

        self.SetWarmUp(100, Resolution.Daily)

    def OnData(self, data):
        self.UpdateMarketState(data)

        if self.IsWarmingUp:
            return

        if not all(data.Bars.ContainsKey(symbol) for symbol in self.symbols):
            return

        spy_bar = data.Bars[self.spy]
        aapl_bar = data.Bars[self.aapl]

        spy_close = spy_bar.Close
        aapl_close = aapl_bar.Close

        spy_ready_for_cross = (
            self.spy_sma.IsReady
            and self.previous_spy_close is not None
            and self.previous_spy_sma is not None
        )

        if self.strategy_a_pending is None:
            if self.strategy_a_lot > 0:
                if (
                    spy_ready_for_cross
                    and self.previous_spy_close >= self.previous_spy_sma
                    and spy_close < self.spy_sma.Current.Value
                ):
                    self.SubmitStrategyASell()
            elif spy_ready_for_cross:
                if (
                    self.previous_spy_close <= self.previous_spy_sma
                    and spy_close > self.spy_sma.Current.Value
                ):
                    quantity = floor(
                        0.40 * float(self.Portfolio.TotalPortfolioValue)
                        / float(spy_close)
                    )
                    if quantity > 0:
                        self.SubmitStrategyABuy(quantity)

        if self.strategy_b_pending is None:
            if self.strategy_b_lot > 0:
                if self.aapl_rsi.IsReady and self.aapl_rsi.Current.Value > 60:
                    self.SubmitStrategyBSell()
            elif self.aapl_red_streak >= 1:
                if self.Portfolio.Cash >= 20000:
                    quantity = floor(20000 / float(aapl_close))
                    if quantity > 0:
                        self.SubmitStrategyBBuy(quantity)

    def UpdateMarketState(self, data):
        if data.Bars.ContainsKey(self.spy):
            spy_close = data.Bars[self.spy].Close

            if self.spy_sma.IsReady:
                self.previous_spy_sma = float(self.spy_sma.Current.Value)

            self.previous_spy_close = float(spy_close)

        if data.Bars.ContainsKey(self.aapl):
            aapl_close = data.Bars[self.aapl].Close

            if self.previous_aapl_close is not None:
                if aapl_close < self.previous_aapl_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0

            self.previous_aapl_close = float(aapl_close)

    def SubmitStrategyABuy(self, quantity):
        ticket = self.MarketOrder(
            self.spy,
            quantity,
            tag="STRATEGY_A_BUY"
        )
        self.strategy_a_pending = ticket.OrderId

    def SubmitStrategyASell(self):
        ticket = self.MarketOrder(
            self.spy,
            -self.strategy_a_lot,
            tag="STRATEGY_A_SELL"
        )
        self.strategy_a_pending = ticket.OrderId

    def SubmitStrategyBBuy(self, quantity):
        ticket = self.MarketOrder(
            self.aapl,
            quantity,
            tag="STRATEGY_B_BUY"
        )
        self.strategy_b_pending = ticket.OrderId

    def SubmitStrategyBSell(self):
        ticket = self.MarketOrder(
            self.aapl,
            -self.strategy_b_lot,
            tag="STRATEGY_B_SELL"
        )
        self.strategy_b_pending = ticket.OrderId

    def OnOrderEvent(self, order_event):
        order = self.Transactions.GetOrderById(order_event.OrderId)
        if order is None:
            return

        tag = order.Tag
        fill_quantity = order_event.FillQuantity

        if tag == "STRATEGY_A_BUY":
            self.strategy_a_lot += fill_quantity
            if order_event.Status == OrderStatus.Filled:
                self.strategy_a_pending = None

        elif tag == "STRATEGY_A_SELL":
            self.strategy_a_lot = max(0, self.strategy_a_lot + fill_quantity)
            if order_event.Status == OrderStatus.Filled:
                self.strategy_a_pending = None

        elif tag == "STRATEGY_B_BUY":
            self.strategy_b_lot += fill_quantity
            if order_event.Status == OrderStatus.Filled:
                self.strategy_b_pending = None

        elif tag == "STRATEGY_B_SELL":
            self.strategy_b_lot = max(0, self.strategy_b_lot + fill_quantity)
            if order_event.Status == OrderStatus.Filled:
                self.strategy_b_pending = None
